  const storagePanel=`<section class="card storage-notice" id="storage-panel" aria-labelledby="storage-heading"><h2 id="storage-heading">${t("சாதனப் பாதுகாப்பு மற்றும் சேமிப்பு விவரம்","Device Privacy & Storage Notice")}</h2><p><strong>${t("பகிரப்பட்ட கணினி எச்சரிக்கை","Shared-device warning")}:</strong> ${t("பள்ளி, கல்லூரி அல்லது பிரவுசிங் மையக் கணினியைப் பயன்படுத்தினால், வெளியேறும் முன் 'விருப்பப்பட்டியலை முழுமையாக அழி' என்பதை அழுத்தவும். அடுத்தவர்கள் உங்கள் விருப்பப்பட்டியலைப் பார்க்க வாய்ப்புள்ளது.","If using a shared computer at a browsing centre, school, or college, click 'Clear entire shortlist' before leaving so future users cannot see your choices.")}</p><p class="supporting">${t("இயல்புநிலை: உலாவி அமர்வு நினைவகம் (Session). உங்கள் தேர்வுகள் இந்த உலாவி அமர்விலும் முகவரி இணைப்பிலும் மட்டுமே இருக்கும். மதிப்பெண்களோ, சாதியோ அல்லது எந்தத் தனிப்பட்ட விவரங்களோ சேமிக்கப்படுவதில்லை.","Default: Browser session memory. Choices are kept in your current session and URL. Strictly zero marks, ranks, community quotas, or personal details are stored.")}</p><div class="storage-options"><label class="storage-checkbox-label" for="storage-opt-in"><input type="checkbox" id="storage-opt-in" name="opt_in_storage" value="1"><span>${t("இந்தச் சாதனத்தில் 30 நாட்கள் வரை சேமி (தனிநபர் சாதனம் மட்டும்)","Save on this device for up to 30 days (personal device only)")}</span></label><p id="storage-expired-msg" class="storage-expired-notice" style="display:none;" role="status">${t("உங்கள் முந்தைய சேமிக்கப்பட்ட தேர்வுகள் 30 நாட்கள் முடிவடைந்ததால் தானாகக் காலாவதியாகி அழிக்கப்பட்டன.","Your previously saved choices expired after 30 days and have been cleared.")}</p></div><div class="storage-actions">${clearBtn}</div></section>`;
