 const storageScript=page==="shortlist"?`<script>(function(){try{var K="tn_guidance_shortlist_v1",r=localStorage.getItem(K);if(r){var d=JSON.parse(r);if(d&&d.expiresAt&&Date.now()>d.expiresAt){localStorage.removeItem(K);var e=document.getElementById("storage-expired-msg");if(e)e.style.display="block";}}var o=document.getElementById("storage-opt-in");if(o){o.checked=!!localStorage.getItem(K);o.addEventListener("change",function(){if(o.checked){var it=${JSON.stringify(validShortlist)};localStorage.setItem(K,JSON.stringify({version:1,savedAt:Date.now(),expiresAt:Date.now()+30*86400*1000,items:it}));}else{localStorage.removeItem(K);}});}var c=document.getElementById("btn-clear-shortlist");if(c){c.addEventListener("click",function(ev){var m="${esc(t("உங்கள் விருப்பப்பட்டியலை முழுமையாக அழிக்க விரும்புகிறீர்களா?","Are you sure you want to clear your entire shortlist?"))}";if(confirm(m)){try{localStorage.removeItem(K);sessionStorage.removeItem(K);}catch(err){}return true;}ev.preventDefault();return false;});}}catch(ex){}})();</script>`:"";
